# The traditional and old public-domain tunes import_abc.py takes from its source collection, with
# the words the Songbook shows. `source` is the tune's title in the collection. Only tunes that are
# traditional, or whose composer died more than 70 years ago and that were published before 1930.
# Optional: stage, tempo, key (to override what the importer works out), collection (when the tune
# is not from the Nottingham Music Database: a folder of music21's corpus, see import_abc.py).

def T(id, title, source, genre, about, story, **kw):
    return dict(id=id, title=title, source=source, genre=genre, about=about, story=story, **kw)

